    def _estimate_tokens(self, text: str) -> int:
        """Estimate token count from text (CJK-aware)."""
        if not text:
            return 0
        ascii_count = 0
        cjk_count = 0
        other_count = 0
        for char in text:
            code = ord(char)
            if (0x4e00 <= code <= 0x9fff) or (0x3400 <= code <= 0x4dbf):
                cjk_count += 1
            elif code < 128:
                ascii_count += 1
            else:
                other_count += 1
        estimated = (ascii_count * 0.75) + (cjk_count * 1.5) + (other_count * 1.0)
        return max(1, int(round(estimated)))

    def _get_request_hash(self, text: str) -> str:
        """Generate deterministic hash for request text."""
        return hashlib.sha256(text.encode('utf-8')).hexdigest()[:16]

    def _cleanup_old_hashes(self, current_time: float):
        """Remove hashes older than the duplicate window."""
        cutoff = current_time - self.duplicate_window_seconds
        expired = [h for h, data in self.request_hashes.items()
                   if data['timestamps'] and data['timestamps'][-1] < cutoff]
        for h in expired:
            del self.request_hashes[h]

    def check(self, text: str, model: str) -> CheckDecision:
        """Perform pre-flight check on a request."""
        self.total_checks += 1
        current_time = time.time()
        if model not in self.models:
            self.models[model] = ModelConfig(
                tpm_limit=self.DEFAULT_QUOTAS.get(model, 1_000_000),
                soft_limit_pct=80.0, hard_limit_pct=95.0
            )
            self.model_usage[model] = 0
        config = self.models[model]
        estimated_tokens = self._estimate_tokens(text)
        req_hash = self._get_request_hash(text)
        self._cleanup_old_hashes(current_time)
        if req_hash in self.request_hashes:
            hash_data = self.request_hashes[req_hash]
            recent = [t for t in hash_data['timestamps']
                     if current_time - t < self.duplicate_window_seconds]
            if len(recent) >= 3:
                self.blocks += 1
                self.tokens_saved += estimated_tokens
                return CheckDecision(action="block", estimated_tokens=estimated_tokens,
                    reason=f"Runaway duplicate ({len(recent)} occurrences)")
            elif len(recent) >= 1:
                if self.cache_enabled and req_hash in self.cache:
                    self.tokens_saved += estimated_tokens
                    return CheckDecision(action="proceed", estimated_tokens=estimated_tokens,
                        reason="Cached response available")
        current_usage = self.model_usage.get(model, 0)
        usage_pct = (current_usage / config.tpm_limit) * 100 if config.tpm_limit > 0 else 0
        new_usage = current_usage + estimated_tokens
        new_usage_pct = (new_usage / config.tpm_limit) * 100 if config.tpm_limit > 0 else 0
        if new_usage_pct > config.hard_limit_pct:
            self.blocks += 1
            self.tokens_saved += estimated_tokens
            return CheckDecision(action="block", estimated_tokens=estimated_tokens,
                reason=f"Hard limit exceeded ({usage_pct:.1f}% used)")
        elif new_usage_pct > config.soft_limit_pct:
            wait_time = (new_usage_pct - config.soft_limit_pct) * 0.5
            return CheckDecision(action="wait", estimated_tokens=estimated_tokens,
                reason=f"Soft limit approaching ({usage_pct:.1f}% used)", wait_seconds=min(wait_time, 60))
        if usage_pct > 90 and len(self.models) > 1:
            for alt_model, alt_config in self.models.items():
                if alt_model != model:
                    alt_usage = self.model_usage.get(alt_model, 0)
                    alt_pct = (alt_usage / alt_config.tpm_limit) * 100 if alt_config.tpm_limit > 0 else 0
                    if alt_pct < 80:
                        self.fallbacks += 1
                        return CheckDecision(action="fallback", estimated_tokens=estimated_tokens,
                            reason=f"Primary near limit ({usage_pct:.1f}%), suggest {alt_model}", fallback_model=alt_model)
        return CheckDecision(action="proceed", estimated_tokens=estimated_tokens)
