    def record_usage(self, tokens: int, model: str):
        """Record actual token usage for a model."""
        if model not in self.model_usage:
            self.model_usage[model] = 0
        self.model_usage[model] += tokens

    def cache_response(self, text: str, response: str):
        """Cache a successful response."""
        if self.cache_enabled:
            req_hash = self._get_request_hash(text)
            self.cache[req_hash] = response
            if req_hash not in self.request_hashes:
                self.request_hashes[req_hash] = {'timestamps': [], 'model': None}
            self.request_hashes[req_hash]['timestamps'].append(time.time())

    def record_request(self, text: str, model: str):
        """Record a request for duplicate detection."""
        req_hash = self._get_request_hash(text)
        current_time = time.time()
        if req_hash not in self.request_hashes:
            self.request_hashes[req_hash] = {'timestamps': [], 'model': model}
        self.request_hashes[req_hash]['timestamps'].append(current_time)
        self.request_hashes[req_hash]['model'] = model

    def get_status(self) -> Dict[str, Any]:
        """Get current status report."""
        models_status = {}
        for model, config in self.models.items():
            used = self.model_usage.get(model, 0)
            remaining = max(0, config.tpm_limit - used)
            usage_pct = (used / config.tpm_limit) * 100 if config.tpm_limit > 0 else 0
            if usage_pct < config.soft_limit_pct:
                status = "OK"
            elif usage_pct < config.hard_limit_pct:
                status = "Warning"
            else:
                status = "Blocked"
            models_status[model] = {
                "tpm_limit": config.tpm_limit,
                "used_this_minute": used,
                "remaining": remaining,
                "usage_pct": f"{usage_pct:.1f}%",
                "status": status
            }
        return {
            "models": models_status,
            "stats": {
                "total_checks": self.total_checks,
                "tokens_saved": self.tokens_saved,
                "blocks": self.blocks,
                "fallbacks": self.fallbacks
            }
        }

    def get_cache_data(self) -> Dict[str, Any]:
        """Get cache data for persistence."""
        current_time = time.time()
        cache_entries = {}
        for req_hash, data in self.request_hashes.items():
            recent = [t for t in data['timestamps'] if current_time - t < self.duplicate_window_seconds]
            cache_entries[req_hash] = {
                "timestamps": recent,
                "model": data.get('model'),
                "cached": req_hash in self.cache
            }
        return {
            "request_hashes": cache_entries,
            "model_usage": dict(self.model_usage),
            "generated_at": current_time
        }
