    def process_batch(self, prompts: List[str], model: str) -> List[CheckDecision]:
        """Process a batch of prompts and return decisions."""
        decisions = []
        for prompt in prompts:
            decision = self.check(prompt, model)
            decisions.append(decision)
            if decision.action == "proceed":
                self.record_request(prompt, model)
        return decisions


def main():
    """CLI entry point for TokenGuard."""
    import argparse
    parser = argparse.ArgumentParser(description="TokenGuard - LLM API 429 Prevention Engine")
    parser.add_argument("--config", "-c", help="Path to configuration file")
    parser.add_argument("--prompts", "-p", nargs="+", help="Prompts to process")
    parser.add_argument("--model", "-m", default="gpt-4o", help="Target model")
    parser.add_argument("--report", "-r", help="Path to write status report")
    parser.add_argument("--cache", "-k", help="Path to write cache file")
    args = parser.parse_args()
    guard = TokenGuard(config_path=args.config if args.config else None)
    if args.prompts:
        decisions = guard.process_batch(args.prompts, args.model)
        for i, (prompt, decision) in enumerate(zip(args.prompts, decisions)):
            print(f"[{i+1}] Action: {decision.action} | Tokens: {decision.estimated_tokens}")
            if decision.reason:
                print(f"    Reason: {decision.reason}")
            if decision.action == "fallback" and decision.fallback_model:
                print(f"    Fallback to: {decision.fallback_model}")
    else:
        print("TokenGuard initialized. Use --prompts to process requests.")
    if args.report:
        status = guard.get_status()
        with open(args.report, 'w', encoding='utf-8') as f:
            json.dump(status, f, indent=2)
        print(f"Status report written to {args.report}")
    if args.cache:
        cache_data = guard.get_cache_data()
        with open(args.cache, 'w', encoding='utf-8') as f:
            json.dump(cache_data, f, indent=2)
        print(f"Cache written to {args.cache}")


if __name__ == "__main__":
    main()
ENDOFFILE
